public class Main {
    static String grade(int marks) {
        if (marks >= 75) {
            return "A";
        } else if (marks >= 50) {
            return "B";
        } else if (marks >= 35) {
            return "C";
        } else {
            return "Fail";
        }
    }

    public static void main(String[] args) {
        System.out.println(grade(80) + " " + grade(50) + " " + grade(35) + " " + grade(10));
    }
}

