task.solution:
public class Main {
    static int firstOver(int[] marks, int limit) {
        for (int i = 0; i < marks.length; i++) {
            if (marks[i] > limit) {
                return i;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        System.out.println(firstOver(new int[]{40, 72, 90}, 70) + " " + firstOver(new int[]{10}, 50));
    }
}

